def diff_inventory(old, new):
    added = sorted(new.keys() - old.keys())
    removed = sorted(old.keys() - new.keys())
    changed = {ip: (old[ip], new[ip]) for ip in old.keys() & new.keys() if old[ip] != new[ip]}
    return added, removed, changed

def parse_ps(text):
    rows = []
    for line in text.splitlines():
        if not line.strip():
            continue
        user, pid, cpu, mem, cmd = line.split(None, 4)
        rows.append({"user": user, "pid": int(pid), "cpu": float(cpu), "mem": float(mem), "cmd": cmd})
    return rows

