    {"ip": "198.51.100.23", "path": "/about.html", "status": 200, "bytes": 3300},
]

def top_ips(records, n=3):
    return Counter(r["ip"] for r in records).most_common(n)

def status_histogram(records):
    return dict(sorted(Counter(r["status"] for r in records).items()))

def bytes_per_ip(records):
    totals = defaultdict(int)
    for r in records:
        totals[r["ip"]] += r["bytes"]
    return sorted(totals.items(), key=lambda kv: (-kv[1], kv[0]))

def errors_by_ip(records):
    bad = defaultdict(set)
    for r in records:
        if r["status"] >= 400:
            bad[r["ip"]].add(r["path"])
    return {ip: sorted(paths) for ip, paths in bad.items()}

def report(records):
    print(f"requests: {len(records)}")
    print("top clients:")
    for ip, n in top_ips(records):
        print(f"  {ip:<16}{n:>3}")
    print("status codes:")
    for code, n in status_histogram(records).items():
        print(f"  {code}  {'#' * n} ({n})")
    print("bytes per client:")
    for ip, total in bytes_per_ip(records):
        print(f"  {ip:<16}{total:>6}")
    print("clients with errors:", errors_by_ip(records))

report(RECORDS)

#!/usr/bin/env python3
"""loganalyzer.py - summarize a web-server access log (core, step 1)."""
from collections import Counter, defaultdict


def parse_line(line):
    parts = line.split('"')
    if len(parts) < 3:
        return None
    request = parts[1].split()
    tail = parts[2].split()
    if len(request) != 3 or len(tail) != 2 or not tail[0].isdigit():
        return None
    return {
        "ip": line.split()[0],
        "time": line.partition("[")[2].partition("]")[0],
        "method": request[0],
        "path": request[1],
        "status": int(tail[0]),
        "bytes": 0 if tail[1] == "-" else int(tail[1]),
    }


def parse_log(text):
    records, bad = [], 0
    for line in text.splitlines():
        if line.strip():
            rec = parse_line(line)
            if rec is None:
                bad += 1
            else:
                records.append(rec)
    return records, bad


def top_ips(records, n=3):
    return Counter(r["ip"] for r in records).most_common(n)


def status_histogram(records):
    return dict(sorted(Counter(r["status"] for r in records).items()))


def bytes_per_ip(records):
    totals = defaultdict(int)
    for r in records:
        totals[r["ip"]] += r["bytes"]
    return sorted(totals.items(), key=lambda kv: (-kv[1], kv[0]))


if __name__ == "__main__":
    with open("access.log") as f:
        records, bad = parse_log(f.read())
    print(len(records), "records,", bad, "unparsable")
    print(top_ips(records, 5))
    print(status_histogram(records))
    print(bytes_per_ip(records)[:3])
